/* cu-effects:apple — Apple 1:1 flagship. Light-first: pure-white base view over
   the #F2F2F7 grouped canvas, systemBlue (#007AFF) accent, translucent bar
   materials (saturate(180%) blur(20px)), hairline separators, pill CTAs,
   17px body / 600 headline weight, 300ms UIKit ease-in-out motion, gentle
   brightness hover and dim-on-press. Proprietary fonts and icon glyphs are
   intentionally NOT replicated. Reference: Human Interface Guidelines (color,
   typography, materials, motion). */
:root {
  --cu-focus-halo: color-mix(in srgb, var(--cu-color-palette-brand) 35%, transparent);
  color-scheme: light;
  -webkit-font-smoothing: antialiased;
  background-color: var(--cu-color-background-subtle);
}

:root[data-color-scheme='dark'] {
  color-scheme: dark;
}

:root .cu-app-shell {
  background-color: var(--cu-color-background-subtle);
}

:root .cu-app-shell__main {
  background-color: var(--cu-color-background-default);
  background-image: none;
}

:root .cu-app-shell__footer {
  background: transparent;
  color: var(--cu-color-fg-muted);
}

/* Bar material: translucent + vibrancy on every piece of chrome */
:root .cu-app-shell__header,
:root .cu-navigation-title,
:root .cu-navigation-bar,
:root .cu-navbar,
:root .cu-tab-bar,
:root .cu-navigation,
:root .cu-sidebar,
:root .cu-app-shell__sidebar,
:root .cu-three-end-chrome {
  background: var(--cu-color-background-translucent);
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
  backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
}

:root .cu-app-shell__header,
:root .cu-navbar {
  border-block-end: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
}

:root .cu-tab-bar {
  border-block-start: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
}

/* iOS tab bar: active item takes the accent tint */
:root .cu-tab-bar__item[data-state='active'] {
  border-block-start-color: transparent;
  color: var(--cu-color-palette-brand);
  font-weight: var(--cu-font-weight-semibold);
}

:root .cu-sidebar,
:root .cu-app-shell__sidebar {
  border-inline-end: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
}

/* Sidebar selection = systemFill wash, not accent paint */
:root .cu-sidebar__item[aria-current='page'],
:root .cu-navigation__item[aria-current='page'] {
  border-inline-start: none;
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-fill-secondary);
  color: var(--cu-color-fg-default);
  font-weight: var(--cu-typography-weight-semibold, 600);
}

@media (hover: hover) {
  :root .cu-sidebar__item:hover,
  :root .cu-navigation__item:hover {
    background: var(--cu-color-fill-tertiary);
  }
}

:root .cu-heading,
:root .cu-typography--heading-1,
:root .cu-typography--heading-2,
:root .cu-navigation-title__title,
:root .cu-navigation-bar__title {
  font-weight: var(--cu-typography-weight-semibold, 600);
}

/* —— Buttons: pill CTAs (App Store "Get" pattern), restrained states —— */
:root .cu-button {
  border-radius: 9999px;
  font-weight: var(--cu-typography-weight-semibold, 600);
  transition:
    background-color var(--cu-motion-duration-fast, 150ms) var(--cu-motion-easing-standard, ease-in-out),
    color var(--cu-motion-duration-fast, 150ms) var(--cu-motion-easing-standard, ease-in-out),
    opacity var(--cu-motion-duration-fast, 150ms) var(--cu-motion-easing-standard, ease-in-out),
    filter var(--cu-motion-duration-fast, 150ms) var(--cu-motion-easing-standard, ease-in-out);
}

:root .cu-button:disabled {
  opacity: 0.5;
}

/* Press = dim, like a UIControl highlight — no aggressive scale */
:root .cu-button:active:not(:disabled) {
  filter: brightness(0.92);
}

:root .cu-button--solid {
  color: #ffffff;
  background: var(--cu-color-palette-brand);
  border-color: transparent;
  box-shadow: none;
}

/* Secondary = gray fill pill (iOS tinted-button style) */
:root .cu-button--outline {
  color: var(--cu-color-palette-brand);
  background: var(--cu-color-fill-tertiary);
  border-color: transparent;
  box-shadow: none;
}

:root .cu-button--ghost {
  color: var(--cu-color-palette-brand);
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}

:root .cu-button--tone-danger.cu-button--solid {
  background: var(--cu-color-palette-danger);
  border-color: transparent;
  color: #ffffff;
  box-shadow: none;
}

:root .cu-button--tone-danger.cu-button--outline,
:root .cu-button--tone-danger.cu-button--ghost {
  color: var(--cu-color-palette-danger);
  border-color: transparent;
  box-shadow: none;
}

:root .cu-button--tone-danger.cu-button--outline {
  background: color-mix(in srgb, var(--cu-color-palette-danger) 12%, transparent);
}

@media (hover: hover) {
  :root .cu-button--solid:hover:not(:disabled),
  :root .cu-upload__browse:hover {
    filter: brightness(1.08); /* Gentle lift — desktop hover stays quiet */
  }

  :root .cu-button--outline:hover:not(:disabled),
  :root .cu-button--ghost:hover:not(:disabled) {
    background: var(--cu-color-fill-secondary);
  }
}

/* macOS-style focus halo in the accent color */
:root .cu-button:focus-visible,
:root .cu-input:focus-visible,
:root .cu-select__trigger:focus-visible,
:root .cu-upload__dropzone:focus-visible {
  outline: none;
  box-shadow: 0 0 0 4px var(--cu-focus-halo);
}

/* —— Upload: plain grouped-surface dropzone + solid blue pill browse CTA —— */
:root .cu-upload__dropzone {
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-5, var(--cu-space-4));
  padding-inline: var(--cu-space-4);
  border: var(--cu-border-width-hairline, 1px) dashed var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-elevated);
  box-shadow: none;
}

:root .cu-upload--dragover .cu-upload__dropzone {
  border-style: solid;
  border-color: var(--cu-color-palette-brand);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 8%, transparent);
  box-shadow: none;
}

:root .cu-upload__browse {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: 2.5rem;
  min-block-size: 2.5rem;
  padding-block: 0;
  padding-inline: var(--cu-space-4);
  border: var(--cu-border-width-default, 1px) solid transparent;
  border-radius: 9999px;
  background: var(--cu-color-palette-brand);
  color: #ffffff;
  font-weight: var(--cu-typography-weight-semibold, 600);
  box-shadow: none;
  transition:
    background-color var(--cu-motion-duration-fast, 150ms) var(--cu-motion-easing-standard, ease-in-out),
    opacity var(--cu-motion-duration-fast, 150ms) var(--cu-motion-easing-standard, ease-in-out),
    filter var(--cu-motion-duration-fast, 150ms) var(--cu-motion-easing-standard, ease-in-out);
}

:root .cu-upload__browse:active {
  filter: brightness(0.92);
}

:root .cu-upload__file {
  border: none;
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-elevated);
}

/* —— Surfaces: grouped cells sit flat on the gray canvas, no shadows —— */
:root .cu-empty-state {
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-6, var(--cu-space-5));
  padding-inline: var(--cu-space-5, var(--cu-space-4));
  border: none;
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-elevated);
  box-shadow: none;
}

:root .cu-empty-state__action {
  margin-block-start: var(--cu-space-3);
  inline-size: min(100%, 22rem);
}

:root .cu-empty-state__action .cu-upload,
:root .cu-empty-state__action .cu-upload__dropzone {
  inline-size: 100%;
}

:root .cu-empty-state__description,
:root .cu-typography--caption,
:root .cu-field__label {
  color: var(--cu-color-fg-muted);
}

:root .cu-card,
:root .cu-card--default {
  border: none;
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-elevated);
  box-shadow: none;
}

:root .cu-card--outlined {
  border: var(--cu-border-width-hairline) solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-elevated);
  box-shadow: none;
}

:root .cu-card--elevated {
  border: none;
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-elevated);
  box-shadow: var(--cu-shadow-md);
}

/* —— Overlays: thick material, alert radius, large soft shadow —— */
:root .cu-dialog__backdrop {
  background: rgba(0, 0, 0, 0.4);
}

:root .cu-dialog__content,
:root .cu-action-sheet__content,
:root .cu-command-palette__content,
:root .cu-sheet,
:root .cu-drawer {
  background: var(--cu-color-background-translucent-thick);
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-thick));
  backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-thick));
  box-shadow: var(--cu-shadow-overlay);
  border-radius: var(--cu-radius-lg);
}

:root .cu-popover__content,
:root .cu-menu,
:root .cu-hover-card,
:root .cu-toast {
  background: var(--cu-color-background-translucent-thick);
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
  backdrop-filter: saturate(var(--cu-saturate-frost)) blur(var(--cu-blur-frost));
  box-shadow: var(--cu-shadow-soft);
  border-radius: var(--cu-radius-lg);
  border-width: var(--cu-border-width-hairline);
}

:root .cu-input,
:root .cu-select__trigger {
  border: none;
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-fill-quaternary);
}

/* —— Transparent media: quiet checker on the light canvas —— */
:root .cu-checkerboard-surface {
  --cu-checkerboard-mix-a: 12%;
  --cu-checkerboard-mix-b: 4%;
}

:root .cu-checkerboard-surface[data-contrast='strong'] {
  --cu-checkerboard-mix-a: 18%;
  --cu-checkerboard-mix-b: 6%;
}

:root .cu-mask-paint-canvas__stage {
  --cu-mask-paint-stage-bg: var(--cu-color-background-subtle);
}

:root .cu-mask-paint-canvas__checker {
  box-shadow: 0 0 0 var(--cu-border-width-hairline, 1px) var(--cu-color-border-default);
}

@media (prefers-reduced-transparency: reduce) {
  :root .cu-app-shell__header,
  :root .cu-navigation-title,
  :root .cu-navigation-bar,
  :root .cu-navbar,
  :root .cu-tab-bar,
  :root .cu-navigation,
  :root .cu-sidebar,
  :root .cu-app-shell__sidebar,
  :root .cu-three-end-chrome,
  :root .cu-dialog__content,
  :root .cu-action-sheet__content,
  :root .cu-command-palette__content,
  :root .cu-sheet,
  :root .cu-drawer,
  :root .cu-popover__content,
  :root .cu-menu,
  :root .cu-hover-card,
  :root .cu-toast {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    background: var(--cu-color-background-elevated);
  }
}

/* Reduced motion: base guard loses specificity to the :root overrides above, so re-assert here. */
@media (prefers-reduced-motion: reduce) {
  :root .cu-button:active:not(:disabled),
  :root .cu-upload__browse:active {
    filter: none;
  }
}

{
  "$description": "Apple dark scheme — manual switch via ThemeProvider colorScheme=\"dark\" ([data-color-scheme=\"dark\"]). Extends the light flagship tokens and flips surfaces / fg / fills / shadows to the iOS dark ramp (systemBlue #0A84FF, pure-black base, gray elevated surfaces).",
  "$extends": "./tokens.json",
  "color": {
    "palette": {
      "brand": { "$value": "#0A84FF", "$description": "iOS systemBlue (dark)." },
      "ink": { "$value": "#000000" },
      "paper": { "$value": "#000000" },
      "danger": { "$value": "#FF453A", "$description": "iOS systemRed (dark)." }
    },
    "background": {
      "default": { "$value": "#000000", "$description": "iOS systemBackground (dark) — pure black." },
      "subtle": { "$value": "#1C1C1E", "$description": "iOS secondarySystemBackground (dark) / grouped canvas." },
      "elevated": { "$value": "#2C2C2E", "$description": "iOS tertiarySystemBackground (dark) — cards, raised surfaces." },
      "inverse": { "$value": "#FFFFFF" },
      "translucent": { "$value": "color-mix(in srgb, #1d1d1d 82%, transparent)", "$description": "Dark bar material base." },
      "translucent-thick": { "$value": "color-mix(in srgb, #1d1d1d 94%, transparent)", "$description": "Dark thick material base." }
    },
    "border": {
      "default": { "$value": "rgba(84, 84, 88, 0.6)", "$description": "iOS separator (dark)." }
    },
    "fg": {
      "default": { "$value": "#FFFFFF", "$description": "iOS label (dark)." },
      "muted": { "$value": "rgba(235, 235, 245, 0.6)", "$description": "iOS secondaryLabel (dark)." },
      "inverse": { "$value": "#000000" }
    },
    "fill": {
      "default": { "$value": "rgba(120, 120, 128, 0.36)", "$description": "iOS systemFill (dark)." },
      "secondary": { "$value": "rgba(120, 120, 128, 0.32)", "$description": "iOS secondarySystemFill (dark)." },
      "tertiary": { "$value": "rgba(120, 120, 128, 0.24)", "$description": "iOS tertiarySystemFill (dark)." },
      "quaternary": { "$value": "rgba(120, 120, 128, 0.18)", "$description": "iOS quaternarySystemFill (dark)." }
    }
  },
  "shadow": {
    "sm": { "$value": "0 1px 2px rgba(0, 0, 0, 0.3)" },
    "md": { "$value": "0 4px 16px rgba(0, 0, 0, 0.4)" },
    "lg": { "$value": "0 12px 40px rgba(0, 0, 0, 0.5)" }
  }
}

{
  "$description": "Apple 1:1 flagship — light-first. Reference: Human Interface Guidelines (developer.apple.com/design/human-interface-guidelines) color / typography / materials guidance, iOS system color ramp. Fonts (SF Pro) and icons (SF Symbols) intentionally NOT replicated; the font stack falls back to the platform system font.",
  "radius": {
    "$type": "dimension",
    "sm": { "$value": { "value": 8, "unit": "px" }, "$description": "Small controls (text fields, inline chips)." },
    "md": { "$value": { "value": 10, "unit": "px" }, "$description": "Content cards — iOS grouped-list cell corner radius." },
    "lg": { "$value": { "value": 14, "unit": "px" }, "$description": "Alerts / popovers (iOS alert corner radius)." },
    "xl": { "$value": { "value": 20, "unit": "px" }, "$description": "Sheets and large modal surfaces." }
  },
  "blur": {
    "$type": "dimension",
    "surface": { "$value": { "value": 20, "unit": "px" } },
    "frost": { "$value": { "value": 20, "unit": "px" }, "$description": "Navigation-bar / toolbar material (regular)." },
    "thick": { "$value": { "value": 40, "unit": "px" }, "$description": "Thick material for overlays and sheets." }
  },
  "saturate": {
    "$type": "number",
    "frost": { "$value": 1.8, "$description": "HIG materials pair blur with 180% saturation." }
  },
  "border": {
    "width": {
      "$type": "dimension",
      "hairline": { "$value": { "value": 1, "unit": "px" } },
      "default": { "$value": { "value": 1, "unit": "px" } }
    }
  },
  "shadow": {
    "sm": {
      "$value": "0 1px 2px rgba(0, 0, 0, 0.04)",
      "$description": "iOS content surfaces are nearly shadowless; separation comes from the grouped background."
    },
    "md": {
      "$value": "0 4px 16px rgba(0, 0, 0, 0.08)"
    },
    "lg": {
      "$value": "0 12px 40px rgba(0, 0, 0, 0.12)",
      "$description": "Large, soft overlay shadow (alerts, sheets) — never harsh."
    },
    "soft": { "$value": "{shadow.md}" },
    "overlay": { "$value": "{shadow.lg}" },
    "none": { "$value": "none" }
  },
  "effect": {
    "frost": { "$value": "saturate(180%) blur(20px)" },
    "frost-thick": { "$value": "saturate(180%) blur(40px)" }
  },
  "font": {
    "family": {
      "sans": {
        "$value": "system-ui, sans-serif",
        "$description": "Platform system font; SF Pro is deliberately not referenced."
      }
    },
    "weight": {
      "semibold": { "$value": 600 }
    }
  },
  "color": {
    "palette": {
      "brand": { "$value": "#007AFF", "$description": "iOS systemBlue (light) — links, primary actions, active tint." },
      "ink": { "$value": "#000000", "$description": "iOS label (light) is pure black." },
      "paper": { "$value": "#FFFFFF", "$description": "iOS systemBackground (light)." },
      "danger": { "$value": "#FF3B30", "$description": "iOS systemRed (light) — destructive actions." }
    },
    "background": {
      "default": { "$value": "#FFFFFF", "$description": "iOS systemBackground — primary (overall) view." },
      "subtle": { "$value": "#F2F2F7", "$description": "iOS systemGroupedBackground — grouped content canvas." },
      "elevated": { "$value": "#FFFFFF", "$description": "iOS secondarySystemGroupedBackground — grouped cells / cards." },
      "inverse": { "$value": "#000000" },
      "translucent": { "$value": "color-mix(in srgb, #f9f9f9 82%, transparent)", "$description": "Light bar material base." },
      "translucent-thick": { "$value": "color-mix(in srgb, #f9f9f9 94%, transparent)", "$description": "Light thick material base." }
    },
    "border": {
      "default": { "$value": "rgba(60, 60, 67, 0.29)", "$description": "iOS separator (light)." }
    },
    "fg": {
      "default": { "$value": "#000000", "$description": "iOS label (light)." },
      "muted": { "$value": "rgba(60, 60, 67, 0.6)", "$description": "iOS secondaryLabel (light)." },
      "inverse": { "$value": "#FFFFFF" }
    },
    "fill": {
      "$type": "color",
      "default": { "$value": "rgba(120, 120, 128, 0.2)", "$description": "iOS systemFill." },
      "secondary": { "$value": "rgba(120, 120, 128, 0.16)", "$description": "iOS secondarySystemFill — selection / active wash." },
      "tertiary": { "$value": "rgba(120, 120, 128, 0.12)", "$description": "iOS tertiarySystemFill — hover wash." },
      "quaternary": { "$value": "rgba(120, 120, 128, 0.08)", "$description": "iOS quaternarySystemFill — faintest grouping fill." }
    }
  },
  "motion": {
    "duration": {
      "fast": { "$value": "150ms", "$description": "Control state changes (hover, highlight)." },
      "base": { "$value": "300ms", "$description": "UIKit default animation duration (0.3s)." },
      "slow": { "$value": "500ms", "$description": "Sheet / large view transitions." }
    },
    "easing": {
      "standard": { "$value": "cubic-bezier(0.42, 0, 0.58, 1)", "$description": "UIKit ease-in-out." },
      "enter": { "$value": "cubic-bezier(0, 0, 0.2, 1)", "$description": "Decelerate into view." },
      "exit": { "$value": "cubic-bezier(0.4, 0, 1, 1)", "$description": "Accelerate out of view." }
    }
  },
  "typography": {
    "size": {
      "caption": { "$value": "0.75rem", "$description": "iOS Caption1: 12pt." },
      "body": { "$value": "1.0625rem", "$description": "iOS Body: 17pt — the default reading size." },
      "heading-3": { "$value": "1.25rem", "$description": "iOS Title3: 20pt." },
      "heading-2": { "$value": "1.75rem", "$description": "iOS Title1: 28pt." },
      "heading-1": { "$value": "2.125rem", "$description": "iOS Large Title: 34pt." }
    },
    "line-height": {
      "tight": { "$value": 1.21, "$description": "Large Title: 41/34." },
      "snug": { "$value": 1.25, "$description": "Title3: 25/20." },
      "body": { "$value": 1.29, "$description": "Body: 22/17." }
    },
    "tracking": {
      "tight": { "$value": "0.012em", "$description": "iOS Large Title carries slight positive tracking (+0.4pt at 34pt)." },
      "body": { "$value": "0em", "$description": "Body tracking left to the platform system font." }
    }
  }
}
